mapper.select:
SELECT 
FROM app_chat_preset
WHERE id = #{id}
  AND scope = 'PRIVATE'
  AND owner_user_id = #{userId}
LIMIT 1

mapper.delete:
DELETE FROM app_chat_preset
WHERE id = #{id}
  AND scope = 'PRIVATE'
  AND owner_user_id = #{userId}

mapper.sql:
WHERE scope = 'PUBLIC'

    AND (
        name LIKE CONCAT('%', #{keyword}, '%')
        OR source_name LIKE CONCAT('%', #{keyword}, '%')
        OR description LIKE CONCAT('%', #{keyword}, '%')
    )


    AND api_type = #{apiType}


    AND enabled = #{enabled}

mapper.delete:
DELETE FROM app_chat_preset
WHERE id = #{id}
  AND scope = 'PUBLIC'
